"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["32560"],{67603(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.sobreposicao_de_janelas_nao_permitida","status":422,"titulo":"Os per\xedodos de duas fases coincidem em parte, e o cadastro n\xe3o permite essa coincid\xeancia"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.sobreposicao_de_janelas_nao_permitida","requisitos":[],"oQueAconteceu":["O cadastro de fases diz que uma fase precede outra e que as duas n\xe3o podem se\\nsobrepor. No cronograma enviado, as duas t\xeam per\xedodo, e a antecessora termina\\ndepois do in\xedcio da sucessora. A mensagem da resposta diz: \\"O per\xedodo desta fase\\ncoincide em parte com o da fase anterior, e o cadastro n\xe3o permite essa\\ncoincid\xeancia.\\"","Terminar exatamente no instante em que a sucessora come\xe7a \xe9 aceito. A confer\xeancia\\ns\xf3 se aplica quando as duas fases t\xeam in\xedcio e fim definidos, e s\xf3 \xe0s rela\xe7\xf5es\\nque pro\xedbem a sobreposi\xe7\xe3o; rela\xe7\xf5es que a permitem n\xe3o s\xe3o afetadas. Nada \xe9\\ngravado, e o cronograma anterior continua como estava.","A recusa vale ao definir o cronograma e tamb\xe9m na publica\xe7\xe3o e na retifica\xe7\xe3o em\\nato \xfanico, porque o cadastro de preced\xeancia pode mudar depois de o cronograma ser\\ngravado. O campo da recusa depende da opera\xe7\xe3o:","- ao definir o cronograma (`PUT`), \xe9 `fases[i].inicio`, em que `i` \xe9 a posi\xe7\xe3o, no\\n  corpo enviado, da fase sucessora do par de preced\xeancia (a que vem depois); a\\n  resposta n\xe3o traz identificadores;\\n- na publica\xe7\xe3o e na retifica\xe7\xe3o, \xe9 `/cronograma/fases/{i}/inicio`, em que `i` \xe9 a\\n  posi\xe7\xe3o da fase sucessora no documento, e a resposta traz o c\xf3digo da fase\\n  sucessora em `identificadores`, no formato\\n  `[{\\"lista\\": \\"fases\\", \\"identificador\\": \\"<c\xf3digo da fase sucessora>\\"}]`.","A recusa s\xf3 acontece quando a ordem n\xe3o est\xe1 invertida e o cadastro n\xe3o permite a\\nsobreposi\xe7\xe3o. Com a ordem invertida, a recusa \xe9 a de\\n[preced\xeancia violada](/erros/uniplus.selecao.processo_seletivo.precedencia_fase_violada);\\ne, se a escolha \\"no mesmo momento da anterior\\" junta as duas fases, mesmo com a\\nordem invertida, a recusa \xe9 a de\\n[fases ligadas por preced\xeancia no mesmo momento](/erros/uniplus.selecao.processo_seletivo.fases_com_precedencia_no_mesmo_momento)."],"comoResolver":["Ajuste os per\xedodos para que a fase antecessora termine at\xe9 o instante em que a\\nsucessora come\xe7a, e envie de novo o cronograma. Se a sobreposi\xe7\xe3o for desejada,\\na permiss\xe3o vem do cadastro de fases, mantido pela unidade respons\xe1vel pelo\\ncat\xe1logo, e n\xe3o pode ser concedida no cronograma do processo."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);